function read(file) {
  const b = fs.readFileSync(file);
  return b.toString(b[0] === 0xff && b[1] === 0xfe ? 'utf16le' : 'utf8').replace(/^\uFEFF/, '');
}
const json = file => JSON.parse(read(file));
