const table = (headers, rows) => `| ${headers.join(' | ')} |\n| ${headers.map(() => '---').join(' | ')} |\n${rows.map(row => `| ${row.map(esc).join(' | ')} |`).join('\n')}\n`;
const write = (name, text) => fs.writeFileSync(`${dir}/${name}`, text.trim() + '\n');
const rel = file => path.relative(dir, file).replaceAll('\\', '/');
const ref = (file, label = file) => `[${label}](${file})`;
function tap(file, prefix) {
  const text = read(file), lines = text.split(/\r?\n/), rows = [];
  for (const [i, line] of lines.entries()) {
    const m = line.match(/^(not ok|ok) \d+ - (.+)$/);
    if (m) rows.push({ id: `${prefix}-${rows.length + 1}`, module: prefix === 'NODE' ? 'Backend Node suite' : 'Frontend isolated units', feature: m[2].replace(/ # SKIP.*$/, ''), status: /# SKIP/.test(m[2]) ? 'BLOCKED' : m[1] === 'ok' ? 'PASS' : 'FAIL', actual: /# SKIP/.test(m[2]) ? 'Environment-gated staging test skipped; no service-backed result.' : `TAP ${m[1]} at line ${i + 1}`, evidence: rel(file), line: i + 1 });
  }
  return { rows, counts: Object.fromEntries([...text.matchAll(/^# (tests|pass|fail|skipped|cancelled) (\d+)$/gm)].map(m => [m[1], +m[2]])) };
}
